insert into public.recipes(id, doc, published, published_at, sort_hint) values ('desk-deep-work', '{"id":"desk-deep-work","schemaVersion":3,"version":3,"title":"Desk: Deep Work","description":"Tap when you sit down to work. Social media and video apps are blocked and notifications go quiet until the timer ends. Tapping again won''t stop it; End early in the app will.","placementHint":"Stick it on your desk where your phone rests, or under the desk edge.","mode":"toggle","params":[{"key":"autoOffMinutes","type":"duration","label":"Turn off automatically after","default":90,"min":15,"max":480}],"autoOffMinutes":"{{autoOffMinutes}}","rules":[{"actions":[{"type":"blockGroups","groups":["social","video"]},{"type":"dnd"}]}],"space":{"name":"Desk","colour":"tomato"},"place":"desk","tagCanEnd":false}'::jsonb, true, '2026-11-01T00:00:00Z', 0)
