insert into public.recipes(id, doc, published, published_at, sort_hint) values ('bed-sleep', '{"id":"bed-sleep","schemaVersion":3,"version":4,"title":"Bed: Sleep Mode","description":"Tap at bedtime to block distracting apps and silence notifications. Sleep mode ends at your wake-up time, or later if you went to bed late, and starts your morning routine.","placementHint":"Stick it on your bedside table where your phone stays overnight.","mode":"toggle","params":[{"key":"usualBedtime","type":"time","label":"Usual bedtime","default":1380,"min":0,"max":1439},{"key":"wakeAt","type":"time","label":"Wake up at","default":300,"min":0,"max":1439,"renamedFrom":"sleepEnd"},{"key":"latestWake","type":"time","label":"Latest wake-up","default":480,"min":0,"max":1439},{"key":"napMinutes","type":"duration","label":"Nap length","default":60,"min":15,"max":240}],"rules":[{"when":{"time":"{{usualBedtime-180}}-{{wakeAt}}"},"actions":[{"type":"blockGroups","groups":["social","video","games"]},{"type":"dnd"}]},{"actions":[{"type":"log","label":"Bed tap outside night hours"}]}],"endActions":[{"type":"checklist","title":"Good morning","items":["Drink a glass of water","Make the bed","Put on workout clothes"]}],"space":{"name":"Bed","colour":"deep_blue"},"place":"bed","tagCanEnd":false,"endPolicy":{"type":"wake","wakeAt":"{{wakeAt}}","usual":"{{usualBedtime}}","latest":"{{latestWake}}","nap":"{{napMinutes}}"}}'::jsonb, true, '2026-11-01T00:00:00Z', 10)
