insert into public.recipes(id, doc, published, published_at, sort_hint) values ('gym-bag', '{"id":"gym-bag","schemaVersion":1,"version":2,"title":"Gym Bag: Workout","description":"Tap when you pick up your gym bag. Starts a one hour workout timer and logs the workout.","placementHint":"Stick it inside your gym bag or on its strap.","mode":"oneShot","rules":[{"actions":[{"type":"timer","minutes":60},{"type":"log","label":"Workout"},{"type":"checklist","title":"Before you go","items":["Water bottle","Headphones","Towel"]}]}],"space":{"name":"Gym bag","colour":"green"},"place":"workout"}'::jsonb, true, '2026-11-01T00:00:00Z', 20)
